1	// Soporte exclusivo de las pruebas de spec-0. Complementa factory/regresion/helpers.ts (que este spec no puede editar).
2	// Selectores tomados del código de Moodle 5.3 en entorno/.moodle-src/. Las aserciones que deciden si un criterio se
3	// cumple están en los .spec.ts; acá solo hay esperas y comprobaciones de que cada paso auxiliar terminó bien.
4	import { expect, type Locator, type Page } from '@playwright/test';
5	import { bloquePregunta } from '../../../factory/regresion/helpers';
6	
7	export type TipoPregunta = 'multichoice' | 'truefalse' | 'essay';
8	export type Categoria = { id: string; contexto: string };
9	
10	type ConfigMoodle = { courseId: number; contextid: number; sesskey: string };
11	
12	const configMoodle = (page: Page): Promise<ConfigMoodle> =>
13	  page.evaluate(() => (window as unknown as { M: { cfg: ConfigMoodle } }).M.cfg);
14	
15	/** Nombre único que no contiene "Examen de regresión", para que abrirQuiz nunca tome este examen por QUIZ-REG. */
16	export const nombreUnico = (prefijo: string, proyecto: string) => `${prefijo} ${proyecto} ${Date.now()}`;
17	
18	export async function idCursoQA101(page: Page): Promise<number> {
19	  await page.goto('/course/view.php?name=QA101');
20	  return (await configMoodle(page)).courseId;
21	}
22	
23	// ---------------------------------------------------------------------------------------------------------
24	// Examen
25	
26	export async function abrirFormularioExamen(page: Page, curso: number) {
27	  await page.goto(`/course/modedit.php?add=quiz&course=${curso}&section=0`);
28	  await expect(page.locator('#id_introeditor_ifr')).toBeVisible();
29	}
30	
31	/** Guarda con "Save and display" y devuelve el cmid del examen creado o editado. */
32	export async function guardarExamen(page: Page): Promise<number> {
33	  await page.getByRole('button', { name: 'Save and display' }).click();
34	  await expect(page).toHaveURL(/mod\/quiz\/view\.php\?id=\d+/);
35	  return Number(new URL(page.url()).searchParams.get('id'));
36	}
37	
38	export async function crearExamen(page: Page, curso: number, nombre: string): Promise<number> {
39	  await abrirFormularioExamen(page, curso);
40	  await page.locator('#id_name').fill(nombre);
41	  return guardarExamen(page);
42	}
43	
44	export async function eliminarExamen(page: Page, cmid: number) {
45	  const { sesskey } = await configMoodle(page);
46	  await page.goto(`/course/mod.php?delete=${cmid}&sesskey=${sesskey}`);
47	  await page.getByRole('button', { name: 'Yes', exact: true }).click();
48	  await expect(page).toHaveURL(/course\/(view|section)\.php/);
49	}
50	
51	// ---------------------------------------------------------------------------------------------------------
52	// Banco de preguntas
53	
54	/** cmid del banco compartido de QA101, leído de la lista de bancos del curso. */
55	export async function cmidBanco(page: Page, curso: number): Promise<number> {
56	  await page.goto(`/question/banks.php?courseid=${curso}`);
57	  const banco = page.locator('.shared-banks .questioncount[data-cmid]').first();
58	  await expect(banco).toBeAttached();
59	  return Number(await banco.getAttribute('data-cmid'));
60	}
61	
62	export const urlCategorias = (banco: number) => `/question/bank/managecategories/category.php?cmid=${banco}`;
63	const urlBanco = (banco: number, c: Categoria) => `/question/edit.php?cmid=${banco}&cat=${c.id},${c.contexto}`;
64	
65	export const filaCategoria = (page: Page, nombre: string): Locator =>
66	  page.locator(`li.qbank_managecategories-item[data-categoryname=${JSON.stringify(nombre)}]`);
67	
68	export const filaPregunta = (page: Page, nombre: string): Locator =>
69	  page.locator('#categoryquestions tbody tr', { hasText: nombre });
70	
71	/**
72	 * Crea una categoría propia en el banco. Es necesaria porque el banco sembrado no tiene categoría por defecto
73	 * (question_bank_helper.php:660 usa skipdefaultcategory): sin esto, las preguntas caerían en Álgebra.
74	 */
75	export async function crearCategoria(page: Page, banco: number, nombre: string): Promise<Categoria> {
76	  await page.goto(urlCategorias(banco));
77	  // El botón recibe su evento cuando el componente reactivo termina de cargar el estado.
78	  await page.waitForLoadState('networkidle');
79	  await page.locator('#qbank_managecategories-addcategory [data-action="addeditcategory"]').click();
80	  const modal = page.locator('[data-region="modal"]').filter({ has: page.locator('input[name="name"]') });
81	  await modal.locator('input[name="name"]').fill(nombre);
82	  await modal.locator('[data-action="save"]').click();
83	  await expect(filaCategoria(page, nombre)).toHaveCount(1);
84	  await page.reload();
85	  const id = await filaCategoria(page, nombre).getAttribute('data-categoryid');
86	  const { contextid } = await configMoodle(page);
87	  return { id: String(id), contexto: String(contextid) };
88	}
89	
90	/** Escribe en un editor TinyMCE. `iframe` es el selector CSS de su iframe. */
91	export async function escribirEditor(page: Page, iframe: string, texto: string) {
92	  await expect(page.locator(iframe)).toBeVisible();
93	  const cuerpo = page.frameLocator(iframe).locator('body');
94	  await cuerpo.click();
95	  await cuerpo.fill(texto);
96	}
97	
98	/** Crea una pregunta desde el botón "Create a new question ..." del banco, dentro de la categoría indicada. */
99	export async function crearPregunta(page: Page, banco: number, categoria: Categoria, tipo: TipoPregunta, nombre: string) {
100	  await page.goto(urlBanco(banco, categoria));
101	  // edit.php:73 corta la página sin pintar el banco mientras la migración de mod_qbank siga en la cola de tareas ad hoc.
102	  await expect(
103	    page.getByRole('alert').filter({ hasText: 'transfer_question_categories' }),
104	    'Entorno: las tareas ad hoc de mod_qbank no terminaron; revisar el cron o ejecutarlas antes de esta prueba',
105	  ).toHaveCount(0);
106	  await page.getByRole('button', { name: /create a new question/i }).click();
107	  await page.locator(`#item_qtype_${tipo}`).check();
108	  await page.locator('#chooserform input.submitbutton').click();
109	  await expect(page).toHaveURL(/question\/bank\/editquestion\/question\.php/);
110	
111	  await page.locator('#id_name').fill(nombre);
112	  await escribirEditor(page, '#id_questiontext_ifr', `Enunciado de ${nombre}`);
113	  if (tipo === 'multichoice') {
114	    await escribirEditor(page, '#id_answer_0_ifr', 'Correcta');
115	    await page.locator('#id_fraction_0').selectOption({ label: '100%' });
116	    await escribirEditor(page, '#id_answer_1_ifr', 'Incorrecta');
117	  } else if (tipo === 'truefalse') {
118	    await page.locator('#id_correctanswer').selectOption({ label: 'True' });
119	  }
120	  await page.locator('#id_submitbutton').click();
121	  await expect(page).toHaveURL(/question\/edit\.php/);
122	  await expect(filaPregunta(page, nombre)).toHaveCount(1);
123	}
124	
125	/** Add > from question bank > Switch bank > filtro de categoría > Add selected questions to the quiz. */
126	export async function agregarDesdeBanco(page: Page, examen: number, banco: number, categoria: string, preguntas: string[]) {
127	  await page.goto(`/mod/quiz/edit.php?cmid=${examen}`);
128	  await page.waitForLoadState('networkidle');
129	  await page.locator('.last-add-menu a[data-bs-toggle="dropdown"]').click();
130	  await page.locator('.last-add-menu [data-action="questionbank"]').click();
131	
132	  // El modal abre en el banco privado del examen; las preguntas están en el banco del curso.
133	  await page.locator('#switch-question-bank').click();
134	  // bank_switcher.js oculta esta selección justo antes de registrar el clic de los enlaces.
135	  await expect(page.locator('.search-banks .form-autocomplete-selection.d-none')).toHaveCount(1);
136	  await page.locator(`a[data-newmodid="${banco}"]`).click();
137	
138	  const filtro = page.locator('[data-filter-type="category"]');
139	  const entrada = filtro.locator('div.form-autocomplete-input input');
140	  await entrada.click();
141	  await entrada.fill(categoria);
142	  await filtro.locator('.form-autocomplete-suggestions li', { hasText: categoria }).click();
143	  await page.locator('[data-filteraction="apply"]').click();
144	
145	  for (const nombre of preguntas) {
146	    await filaPregunta(page, nombre).locator('input[type="checkbox"]').check();
147	  }
148	  await page.getByRole('button', { name: 'Add selected questions to the quiz' }).click();
149	  await expect(page).toHaveURL(/mod\/quiz\/edit\.php/);
150	}
151	
152	/** Borra todas las preguntas de la categoría con la confirmación del banco y comprueba que ya no se listan. */
153	export async function eliminarPreguntas(page: Page, banco: number, categoria: Categoria) {
154	  await page.goto(urlBanco(banco, categoria));
155	  const nombres = await page.locator('#categoryquestions tbody input[type="checkbox"]')
156	    .evaluateAll((casillas) => casillas.map((c) => (c as HTMLInputElement).name));
157	  const ids = nombres.filter((n) => /^q\d+$/.test(n));
158	  if (!ids.length) return;
159	  const { sesskey } = await configMoodle(page);
160	  const parametros = new URLSearchParams({
161	    deleteselected: ids[0].slice(1),
162	    deleteall: '1',
163	    sesskey,
164	    cmid: String(banco),
165	    returnurl: `/question/edit.php?cmid=${banco}`,
166	  });
167	  ids.forEach((q) => parametros.set(q, '1'));
168	  await page.goto(`/question/bank/deletequestion/delete.php?${parametros}`);
169	  await page.getByRole('button', { name: 'Delete', exact: true }).click();
170	  await expect(page).toHaveURL(/question\/edit\.php/);
171	  await page.goto(urlBanco(banco, categoria));
172	  await expect(page.locator('#categoryquestions tbody tr')).toHaveCount(0);
173	}
174	
175	export async function eliminarCategoria(page: Page, banco: number, categoria: Categoria) {
176	  const { sesskey } = await configMoodle(page);
177	  await page.goto(`${urlCategorias(banco)}&delete=${categoria.id}&sesskey=${sesskey}`);
178	  await expect(page).toHaveURL(/managecategories\/category\.php/);
179	}
180	
181	// ---------------------------------------------------------------------------------------------------------
182	// Intento y calificación
183	
184	/** Radio de una opción, con el mismo criterio de nombre accesible que elegir() en helpers.ts. */
185	export function opcion(page: Page, pregunta: number, texto: string): Locator {
186	  return bloquePregunta(page, pregunta).getByRole('radio', { name: new RegExp(`^([a-z0-9]+\\. )?${texto}$`, 'i') });
187	}
188	
189	/** Celda de estado de una pregunta en la tabla de summary.php. */
190	export const estadoEnResumen = (page: Page, pregunta: number): Locator =>
191	  page.locator(`table.quizsummaryofattempt tr.quizsummary${pregunta} td.c1`);
192	
193	/** Desde la última página del intento va a summary.php, sin enviar. */
194	export async function irAlResumen(page: Page) {
195	  await page.getByRole('button', { name: /finish attempt/i }).click();
196	  await expect(page).toHaveURL(/summary\.php/);
197	}
198	
199	export const idIntento = (page: Page) => Number(new URL(page.url()).searchParams.get('attempt'));
200	
201	/**
202	 * Celdas de la columna Time del historial de respuestas de comment.php. prepararCaptura no las cubre y la fábrica
203	 * no puede editar helpers.ts desde este spec. Se ubican por el texto del encabezado, no por posición.
204	 */
205	export async function celdasTiempoHistorial(page: Page): Promise<Locator> {
206	  const tabla = page.locator('div.responsehistoryheader table');
207	  const encabezados = await tabla.locator('thead th').allTextContents();
208	  const columna = encabezados.findIndex((t) => t.trim() === 'Time');
209	  expect(columna, `Encabezados del historial: ${encabezados.join(', ')}`).not.toEqual(-1);
210	  return tabla.locator(`tbody tr > :nth-child(${columna + 1})`);
211	}
